 "content": "def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    from collections import Counter
    rc=Counter(r for r,c in pts)
    cc=Counter(c for r,c in pts)
    # The axis with multiple markers forms the backbone; connect remaining markers
    # to it using straight perpendicular segments.
    best_r=max(rc.values(), default=0)
    best_c=max(cc.values(), default=0)
    if best_c>best_r:
        spine=max(cc, key=cc.get)
        rows=[r for r,c in pts if c==spine]
        for r in range(min(rows)+1,max(rows)):
            if out[r][spine]==0: out[r][spine]=3
        for r,c in pts:
            if c==spine: continue
            for x in range(min(c,spine)+1,max(c,spine)):
                if out[r][x]==0: out[r][x]=3
    else:
        spine=max(rc, key=rc.get)
        cols=[c for r,c in pts if r==spine]
        for c in range(min(cols)+1,max(cols)):
            if out[spine][c]==0: out[spine][c]=3
        for r,c in pts:
            if r==spine: continue
            for x in range(min(r,spine)+1,max(r,spine)):
                if out[x][c]==0: out[x][c]=3
    return out
